from pathlib import Path
import base64,json
root=Path(__file__).resolve().parents[1]
game=Path('D:/Github/spire-codex/extraction/raw/animations/characters')
out=root/'actions-v7/research'
report=json.loads((out/'sts2-character-attachment-audit.json').read_text())
bundle=[]
for c in report['characters']:
    d=game/c['name']
    bundle.append(dict(name=c['name'],binary=base64.b64encode((d/(c['name']+'.skel')).read_bytes()).decode(),atlas=(d/(c['name']+'.atlas')).read_text(),pages={p.name:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in d.glob('*.png')},audit=c))
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>STS2 原版 Spine 动作与附件研究</title><style>body{background:#eee9df;color:#302d2a;font:14px/1.6 system-ui;margin:28px}main{max-width:1220px;margin:auto}h1{font-size:27px}p{color:#786d61}select{font:inherit;padding:7px;margin:0 15px 15px 5px}canvas{width:100%;height:740px;background:#ddd5c7;display:block}pre{white-space:pre-wrap;background:#faf6ee;padding:18px;font:12px/1.7 Consolas,monospace}#error{color:#a32d22}</style><main><h1>原版怎样让同一个部位换图</h1><p>读取本地原版角色 .skel + .atlas，以下由官方 Spine WebGL 运行库实际渲染。附件键数量包含隐藏和初始状态，不等于独立绘图数量。仅用于本地制作研究。</p><label>角色<select id="character" aria-label="原版角色"></select></label><label>动画<select id="clip" aria-label="原版动作"></select></label><canvas id="canvas" aria-label="原版动作六个采样姿势"></canvas><p id="times"></p><p id="error"></p><h2>当前动作的附件键与时刻</h2><pre id="detail"></pre></main><script id="data" type="application/json">__DATA__</script><script>__RUNTIME__</script><script type="module">
const all=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),cv=$('canvas'),gl=cv.getContext('webgl',{alpha:true,antialias:true,preserveDrawingBuffer:true}),renderer=new spine.SceneRenderer(cv,gl);let data,entry,atlas;
$('character').innerHTML=all.map(x=>`<option value="${x.name}">${x.name}</option>`).join('');$('character').value='necrobinder';
async function load(){entry=all.find(x=>x.name===$('character').value);atlas=new spine.TextureAtlas(entry.atlas);await Promise.all(atlas.pages.map(page=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{page.setTexture(new spine.GLTexture(gl,im));resolve()};im.onerror=reject;im.src=entry.pages[page.name]})));data=new spine.SkeletonBinary(new spine.AtlasAttachmentLoader(atlas)).readSkeletonData(Uint8Array.from(atob(entry.binary),c=>c.charCodeAt(0)));$('clip').innerHTML=data.animations.map(x=>`<option>${x.name}</option>`).join('');$('clip').value='attack';draw()}
function pose(anim,time){const sk=new spine.Skeleton(data);anim.apply(sk,0,time,false,[],1,spine.MixBlend.setup,spine.MixDirection.mixIn);sk.updateWorldTransform(spine.Physics.update);return sk}
function draw(){const anim=data.findAnimation($('clip').value),times=entry.name==='necrobinder'&&anim.name==='attack'?[0,.15,.18,.35,.6,.9]:[0,.2,.4,.6,.8,1].map(x=>x*anim.duration);let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const offset=new spine.Vector2(),size=new spine.Vector2();for(const t of times){pose(anim,t).getBounds(offset,size,[]);minX=Math.min(minX,offset.x);minY=Math.min(minY,offset.y);maxX=Math.max(maxX,offset.x+size.x);maxY=Math.max(maxY,offset.y+size.y)}const dpr=Math.min(devicePixelRatio,2);cv.width=cv.clientWidth*dpr;cv.height=740*dpr;gl.viewport(0,0,cv.width,cv.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.enable(gl.SCISSOR_TEST);times.forEach((t,i)=>{const w=Math.floor(cv.width/3),h=Math.floor(cv.height/2),x=(i%3)*w,y=(1-Math.floor(i/3))*h;gl.viewport(x,y,w,h);gl.scissor(x,y,w,h);const scale=Math.min((w/dpr-30)/(maxX-minX),(h/dpr-45)/(maxY-minY));renderer.camera.setViewport(w/dpr/scale,h/dpr/scale);renderer.camera.position.set((minX+maxX)/2,(minY+maxY)/2,0);renderer.camera.update();renderer.begin();renderer.drawSkeleton(pose(anim,t),false);renderer.end()});gl.disable(gl.SCISSOR_TEST);$('times').textContent=times.map((x,i)=>`${i+1}: ${x.toFixed(3)}s`).join('　 /　 ');const a=entry.audit.animations.find(a=>a.name===anim.name);$('detail').textContent=JSON.stringify({version:entry.audit.version,bones:entry.audit.bones,slots:entry.audit.slots,duration:anim.duration,attachmentKeys:a.attachmentKeys,drawOrderKeyTimes:a.drawOrder.map(x=>x.times)},null,2)}
$('character').onchange=()=>load().catch(e=>$('error').textContent=e.stack);$('clip').onchange=draw;addEventListener('resize',()=>data&&draw());load().catch(e=>{$('error').textContent=e.stack;console.error(e)});
</script></html>'''
html=html.replace('__DATA__',json.dumps(bundle,separators=(',',':')).replace('</','<\\/')).replace('__RUNTIME__',(root/'vendor/spine-webgl-4.2.95.min.js').read_text())
(out/'sts2-animation-study.html').write_text(html,encoding='utf-8')
print('Local study:',len(html),'characters')
